result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/outline/src/lint.js", "content": "const { parse } = require('node-html-parser');

/**
 * Lint heading structure of an HTML document.
 *
 * Findings produced:
 *  - 'no-h1'        : document contains no <h1>
 *  - 'multiple-h1'   : more than one <h1> (reported on each h1 after the first)
 *  - 'skipped-level' : heading level increases by more than one (e.g. h2 -> h4)
 *  - 'empty-text'    : heading with no text content
 *
 * Headings are considered in flat document order (no outline-algorithm
 * cleverness), including headings nested inside sections, articles, etc.
 *
 * @param {string} html raw HTML string
 * @returns {Array<{level: number, text: string, problem: string}>}
 */
function lintHeadings(html) {
  const root = parse(html);
  const findings = [];
  const h1s = root.querySelectorAll('h1');
  let prevLevel = 0;

  for (const el of root.querySelectorAll('h1,h2,h3,h4,h5,h6')) {
    const level = Number(el.tagName.slice(1));
    const text = (el.text || '').trim();

    if (!text) {
      findings.push({ level, text, problem: 'empty-text' });
      continue; // don't let empty headings affect level-skip tracking
    }

    if (prevLevel > 0 && level > prevLevel + 1) {
      findings.push({ level, text, problem: 'skipped-level' });
    }

    if (level === 1 && h1s.length > 1 && el !== h1s[0]) {
      findings.push({ level, text, problem: 'multiple-h1' });
    }

    prevLevel = level;
  }

  if (h1s.length === 0) {
    findings.unshift({ level: 0, text: '', problem: 'no-h1' });
  }

  return findings;
}

module.exports = { lintHeadings };
"})
