const { readFileSync } = require('fs');
const { lintHeadings } = require('./lint');

const file = process.argv[2];
if (!file) {
  console.error('usage: node cli.js <file.html>');
  process.exit(2);
}

let html;
try {
  html = readFileSync(file, 'utf8');
} catch (err) {
  console.error(`error: cannot read ${file}: ${err.message}`);
  process.exit(2);
}

const findings = lintHeadings(html);
for (const f of findings) {
  console.log(`${f.level}:${f.problem}:${f.text}`);
}
process.exit(findings.length > 0 ? 1 : 0);
