result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/outline/test/lint.test.js", "content": "const { test } = require('node:test');
const assert = require('node:assert');
const { execFile } = require('node:child_process');
const path = require('node:path');
const { promisify } = require('node:util');

const run = promisify(execFile);
const lintHeadings = require('../src/lint');
const cliPath = path.join(__dirname, '..', 'src', 'cli.js');

// --- inline fixture documents -------------------------------------------

const CLEAN = `
<html><body>
  <h1>Getting Started</h1>
  <section><h2>Installation</h2><p>...</p></section>
  <section><h2>Usage</h2><article><h3>CLI</h3><p>...</p></article></section>
</body></html>`;

const SKIP = `
<html><body>
  <h1>Top</h1>
  <h2>Section</h2>
  <h4>Skipped h3 entirely</h4>
</body></html>`;

const DUPES = `
<html><body>
  <h1>First Title</h1>
  <p>intro</p>
  <h1>Second Title</h1>
  <section><h1>Third Title</h1></section>
</body></html>`;

const EMPTY = `
<html><body>
  <h1>Doc</h1>
  <h2></h2>
  <h3>   </h3>
</body></html>`;

// --- lintHeadings --------------------------------------------------------

test('clean document yields no findings', () => {
  assert.deepStrictEqual(lintHeadings(CLEAN), []);
});

test('skipped level (h2 to h4) is reported', () => {
  assert.deepStrictEqual(lintHeadings(SKIP), [
    { level: 4, text: 'Skipped h3 entirely', problem: 'skipped-level' },
  ]);
});

test('multiple h1s reported on every h1 after the first', () => {
  assert.deepStrictEqual(lintHeadings(DUPES), [
    { level: 1, text: 'Second Title', problem: 'multiple-h1' },
    { level: 1, text: 'Third Title', problem: 'multiple-h1' },
  ]);
});

test('empty heading text is reported; empty headings do not affect skips', () => {
  // h2 is empty -> empty-text only; the following h3 must NOT be a skipped-level
  assert.deepStrictEqual(lintHeadings(EMPTY), [
    { level: 2, text: '', problem: 'empty-text' },
    { level: 3, text: '', problem: 'empty-text' },
  ]);
});

test('document with no h1 at all reports no-h1 first', () => {
  const html = '<html><body><h2>A</h2><h3>B</h3></body></html>';
  assert.deepStrictEqual(lintHeadings(html), [
    { level: 0, text: '', problem: 'no-h1' },
  ]);
});

// --- CLI -----------------------------------------------------------------

test('cli exits 0 and prints nothing for clean fixture', async () => {
  const file = path.join(__dirname, '..', 'fixtures', 'clean.html');
  const { stdout } = await run('node', [cliPath, file]);
  assert.strictEqual(stdout, '');
});

test('cli exits 1 and prints LEVEL:PROBLEM:TEXT lines for messy fixture', async () => {
  const file = path.join(__dirname, '..', 'fixtures', 'messy.html');
  await assert.rejects(
    run('node', [cliPath, file]),
    (err) => {
      assert.strictEqual(err.code, 1);
      const lines = err.stdout.trim().split('\n');
      assert.deepStrictEqual(lines, [
        '4:skipped-level:Deep dive',
        '1:multiple-h1:Duplicated',
        '2:empty-text:',
      ]);
      return true;
    }
  );
});
"})
